(()=>{
 const D=AssessmentData,E=Engineering,key='statics-assessment-v1',lessonFor={resultants:'lesson',geometry:'position',projection:'projection',moments:'moment',axis:'axisCouple',couples:'axisCouple'};
 let saved={version:1,study:{answers:{},checked:{},topic:'all',type:'all',index:0},exam:null,history:[]},storageAvailable=true,mode='study',timer=null;
 function validAttempt(a){return a&&[1,2].includes(a.version)&&Number.isInteger(a.seed)&&Number.isFinite(a.startedAt)&&Number.isFinite(a.deadline)&&a.deadline-a.startedAt===7200000&&['active','submitted','expired'].includes(a.status)&&Array.isArray(a.mc)&&a.mc.length===(a.version===1?8:7)&&Array.isArray(a.tf)&&a.tf.length===(a.version===1?8:6)&&new Set([...a.mc,...a.tf]).size===(a.version===1?16:13)&&[...a.mc,...a.tf].every(id=>D.bank.some(q=>q.id===id))&&a.mc.every(id=>D.bank.find(q=>q.id===id)?.type==='mc')&&a.tf.every(id=>D.bank.find(q=>q.id===id)?.type==='tf')&&a.answers&&typeof a.answers==='object'&&a.work&&typeof a.work==='object'&&Array.isArray(a.flags);}
 try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(parsed.version===1){if(parsed.study?.answers&&parsed.study?.checked)saved.study={...saved.study,...parsed.study};if(validAttempt(parsed.exam))saved.exam=parsed.exam;if(Array.isArray(parsed.history))saved.history=parsed.history.slice(-10);}}}catch{storageAvailable=false;}
 if(!['all',...Object.keys(D.topics)].includes(saved.study.topic))saved.study.topic='all';if(!['all','mc','tf'].includes(saved.study.type))saved.study.type='all';if(!Number.isInteger(saved.study.index))saved.study.index=0;
 $('assessment').innerHTML=`<div class="lesson-strip"><span class="number">EXAM</span><div><h2>Learn the concepts. Test the whole workflow.</h2><p>Original practice aligned with your professor’s topic list.</p></div></div><div class="projection-choices" role="group" aria-label="Assessment mode"><button id="studyMode" aria-pressed="true">Concept quizzes</button><button id="examMode" aria-pressed="false">120-minute mock exam</button></div><p id="assessmentStorage" class="projection-note"></p><section id="studyArea"></section><section id="examArea" hidden></section>`;
 function persist(){try{localStorage.setItem(key,JSON.stringify(saved));}catch{storageAvailable=false;}$('assessmentStorage').textContent=storageAvailable?'Answers and results save in this browser only. They do not sync between devices.':'Browser storage is unavailable. Keep this page open; answers will not survive a reload.';}
 function lock(active){window.examInProgress=active;document.body.classList.toggle('exam-running',active);document.querySelectorAll('nav button').forEach(button=>button.disabled=active&&button.dataset.view!=='assessment');$('studyMode').disabled=active;}
 function setMode(next){if(saved.exam?.status==='active'&&next==='study')return;mode=next;$('studyArea').hidden=mode!=='study';$('examArea').hidden=mode!=='exam';$('studyMode').setAttribute('aria-pressed',String(mode==='study'));$('examMode').setAttribute('aria-pressed',String(mode==='exam'));if(mode==='study')renderStudy();else renderExam();}
 $('studyMode').onclick=()=>setMode('study');$('examMode').onclick=()=>setMode('exam');
 function filtered(){return D.bank.filter(q=>(saved.study.topic==='all'||q.topic===saved.study.topic)&&(saved.study.type==='all'||q.type===saved.study.type));}
 function studySummary(){const completed=D.bank.filter(q=>saved.study.checked[q.id]),correct=completed.filter(q=>Number(saved.study.answers[q.id])===q.answer),missed=completed.filter(q=>Number(saved.study.answers[q.id])!==q.answer);return {completed,correct,missed};}
 function renderStudy(){const pool=filtered();saved.study.index=Math.max(0,Math.min(saved.study.index,pool.length-1));const q=pool[saved.study.index],summary=studySummary(),checked=!!saved.study.checked[q.id],answer=saved.study.answers[q.id],correct=Number(answer)===q.answer;
 $('studyArea').innerHTML=`<div class="assessment-grid"><article class="panel"><div class="quiz-filters"><label>Topic<select id="quizTopic"><option value="all">All exam topics</option>${Object.entries(D.topics).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><label>Question type<select id="quizType"><option value="all">Both types</option><option value="mc">Multiple choice</option><option value="tf">True / false</option></select></label></div><div class="panel-heading"><span class="badge">${q.type==='mc'?'MULTIPLE CHOICE':'TRUE / FALSE'}</span><span class="muted">${saved.study.index+1} / ${pool.length}</span></div><h3>${D.topics[q.topic]}</h3><p class="assessment-prompt">${q.prompt}</p><fieldset class="answer-options"><legend>Choose your answer</legend>${q.options.map((option,i)=>`<label class="answer-option"><input type="radio" name="studyAnswer" value="${i}" ${Number(answer)===i&&answer!==undefined?'checked':''} ${checked?'disabled':''}><span>${option}</span></label>`).join('')}</fieldset><div class="actions"><button id="quizCheck" class="primary" ${checked?'disabled':''}>Check answer</button><button id="quizRetry" ${checked?'':'hidden'}>Try again</button><button id="quizPrevious" ${saved.study.index===0?'disabled':''}>← Previous</button><button id="quizNext" ${saved.study.index===pool.length-1?'disabled':''}>Next →</button></div><div id="quizFeedback" role="status">${checked?`<div class="assessment-feedback ${correct?'correct':'incorrect'}"><strong>${correct?'Correct.':'Review this concept.'}</strong><p>The correct answer is <strong>${q.options[q.answer]}</strong>.</p><p>${q.explanation}</p><button data-review-lesson="${lessonFor[q.topic]}">Open related lesson →</button></div>`:''}</div></article><aside class="panel assessment-progress"><h3>Your concept progress</h3><div class="score-large">${summary.correct.length}<small> / ${summary.completed.length} checked correctly</small></div><p class="projection-note">${D.bank.length} original questions cover all six topic groups. Answers are revealed only after checking.</p><h3>Topics to revisit</h3>${summary.missed.length?`<div class="missed-list">${summary.missed.map(m=>`<button data-missed-question="${m.id}">${D.topics[m.topic]} · ${m.type==='mc'?'MC':'T/F'}</button>`).join('')}</div>`:'<p class="projection-note">No missed checked questions yet.</p>'}</aside></div>`;
 $('quizTopic').value=saved.study.topic;$('quizType').value=saved.study.type;$('quizTopic').onchange=()=>{saved.study.topic=$('quizTopic').value;saved.study.index=0;persist();renderStudy();};$('quizType').onchange=()=>{saved.study.type=$('quizType').value;saved.study.index=0;persist();renderStudy();};
 document.querySelectorAll('input[name="studyAnswer"]').forEach(input=>input.onchange=()=>{saved.study.answers[q.id]=Number(input.value);persist();});$('quizCheck').onclick=()=>{if(saved.study.answers[q.id]===undefined){$('quizFeedback').textContent='Choose an answer before checking.';return;}saved.study.checked[q.id]=true;persist();renderStudy();};$('quizRetry').onclick=()=>{delete saved.study.checked[q.id];delete saved.study.answers[q.id];persist();renderStudy();};$('quizPrevious').onclick=()=>{saved.study.index--;persist();renderStudy();};$('quizNext').onclick=()=>{saved.study.index++;persist();renderStudy();};
 document.querySelectorAll('[data-missed-question]').forEach(button=>button.onclick=()=>{saved.study.topic='all';saved.study.type='all';saved.study.index=D.bank.findIndex(q=>q.id===button.dataset.missedQuestion);persist();renderStudy();});bindLessonLinks();}
 function bindLessonLinks(){document.querySelectorAll('[data-review-lesson]').forEach(button=>button.onclick=()=>showView(button.dataset.reviewLesson));}
 function allQuestions(){const a=saved.exam;return [...D.questions(a),...D.calculations(a.seed,a.version)];}
 function isAnswered(question,a){if(question.fields)return question.fields.every(field=>String(a.answers[question.id]?.[field.id]??'').trim()!=='');return a.answers[question.id]!==undefined;}
 function renderExam(){if(!saved.exam){renderExamStart();return;}if(saved.exam.status!=='active'){renderResults();return;}if(D.remaining(saved.exam)===0){finish('expired');return;}renderActiveExam();}
 function renderExamStart(){lock(false);$('examArea').innerHTML=`<article class="panel exam-setup"><div class="eyebrow">EXAM 1 SIMULATION</div><h2>120 minutes. One equation sheet. Four calculation problems.</h2><p class="assessment-prompt">Practice under your professor’s <strong>closed-book, closed-notes conditions</strong>. Use your own <strong>one letter-sized equation sheet</strong> and the calculator. Lessons, answer explanations, and quiz mode stay unavailable during the attempt.</p><div class="exam-format"><div><strong>7</strong><span>Multiple choice · fundamental concepts</span></div><div><strong>6</strong><span>True / false · fundamental concepts</span></div><div><strong>4</strong><span>Calculation problems · 20 points each (80 total)</span></div></div><p><strong>100 points total.</strong> Concept questions assess fundamental understanding across every topic group. For practice scoring, they share the remaining <strong>20 points equally</strong>; the instructor’s individual concept-question weights have not been specified. Calculation forms cover resultants, cable forces and point moments, axis moments, and couples.</p><p class="projection-note">This is original self-study practice, not your professor’s exam or grading rubric. Numeric entries earn points individually; written work is saved for your review and is not automatically graded. Round forces and moments to 0.1, unit components to 0.005, lengths to 0.01 m, and angles to 0.2° or better.</p><p class="projection-note">The timer continues while you leave or reload the page. It automatically finishes at the deadline. Answers and work save locally when browser storage is available.</p><div class="actions"><button id="startExam" class="primary">Start 120-minute exam</button><button id="examReference">Review equations before starting</button></div>${saved.history.length?`<div class="exam-history"><h3>Recent attempts</h3>${saved.history.slice(-5).reverse().map(h=>`<p>${M.esc(new Date(h.finishedAt).toLocaleDateString())} · <strong>${Number(h.score)} / 100</strong></p>`).join('')}</div>`:''}</article>`;$('startExam').onclick=startExam;$('examReference').onclick=()=>showView('reference');}
 function startExam(){saved.exam=D.createAttempt((Date.now()^Math.floor(Math.random()*4294967296))>>>0);persist();showView('assessment');lock(true);mode='exam';setMode('exam');startTimer();}
 function startTimer(){if(saved.exam?.status!=='active')return;if(timer!==null)clearInterval(timer);timer=setInterval(tick,1000);tick();}
 function timeLabel(ms){const seconds=Math.ceil(ms/1000),h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return [h,m,s].map(v=>String(v).padStart(2,'0')).join(':');}
 function tick(){if(saved.exam?.status!=='active')return;const left=D.remaining(saved.exam);if(left===0){finish('expired');return;}if($('examTimer'))$('examTimer').textContent=timeLabel(left);if($('examTimeNotice'))$('examTimeNotice').textContent=left<=5*60000?'Five minutes or less remain. Review unanswered items.':left<=15*60000?'Fifteen minutes or less remain.':'';}
 function writeAnswer(id,value,field){const a=saved.exam;if(a?.status!=='active')return;if(D.remaining(a)===0){finish('expired');return;}if(field){if(!a.answers[id]||typeof a.answers[id]!=='object')a.answers[id]={};a.answers[id][field]=value;}else a.answers[id]=Number(value);persist();renderQuestionMap();}
 function renderQuestionMap(){if(saved.exam?.status!=='active')return;const a=saved.exam,items=allQuestions(),answered=items.filter(q=>isAnswered(q,a)).length;$('examProgress').textContent=`${answered} / ${items.length} answered`;$('examQuestionMap').innerHTML=items.map((q,i)=>`<button data-exam-question="${i}" aria-label="Question ${i+1}${a.flags.includes(q.id)?', flagged':''}${isAnswered(q,a)?', answered':''}" class="question-chip ${i===a.index?'current':''} ${isAnswered(q,a)?'answered':''}">${i+1}${a.flags.includes(q.id)?' ⚑':''}</button>`).join('');document.querySelectorAll('[data-exam-question]').forEach(button=>button.onclick=()=>{if(D.remaining(a)===0){finish('expired');return;}a.index=Number(button.dataset.examQuestion);persist();renderActiveExam();});}
 function renderActiveExam(){const a=saved.exam,items=allQuestions();a.index=Math.max(0,Math.min(Number(a.index)||0,items.length-1));const q=items[a.index],calc=!!q.fields,points=calc?20:D.conceptPoints(a,q);
 $('examArea').innerHTML=`<div class="exam-toolbar"><div><div class="eyebrow">MOCK EXAM · IN PROGRESS</div><strong id="examProgress"></strong></div><div class="timer-block"><span>TIME REMAINING</span><strong id="examTimer">${timeLabel(D.remaining(a))}</strong></div><button id="finishExam">Finish & grade</button></div><p id="examTimeNotice" class="error" role="status"></p><div id="examQuestionMap" class="question-map"></div><article class="panel exam-question"><div class="panel-heading"><span class="badge">${calc?'CALCULATION':q.type==='mc'?'MULTIPLE CHOICE':'TRUE / FALSE'} · ${E.round(points)} POINTS</span><label class="flag-label"><input id="examFlag" type="checkbox" ${a.flags.includes(q.id)?'checked':''}> Flag for review</label></div><h2>${calc?q.title:`Question ${a.index+1} · ${D.topics[q.topic]}`}</h2><p class="assessment-prompt">${calc?q.prompt:q.prompt}</p>${calc?`<svg id="examCalculationDiagram" viewBox="0 0 600 400" role="img" aria-label="Given problem geometry"></svg><p class="projection-note">Diagram is a projection. Use the stated numerical data rather than measuring the picture. Sketch and solve on paper if preferred.</p><div class="position-answer-grid">${q.fields.map(field=>`<label>${field.label}<input data-exam-field="${field.id}" type="number" step="any" value="${M.esc(a.answers[q.id]?.[field.id]??'')}"></label>`).join('')}</div><label>Working / notes (saved, not automatically graded)<textarea id="examWork" maxlength="4000" rows="5" placeholder="Record your setup, equations, and checks…">${M.esc(a.work[q.id]||'')}</textarea></label>`:`<fieldset class="answer-options"><legend>Choose your answer</legend>${q.options.map((option,i)=>`<label class="answer-option"><input type="radio" name="examAnswer" value="${i}" ${a.answers[q.id]!==undefined&&Number(a.answers[q.id])===i?'checked':''}><span>${option}</span></label>`).join('')}</fieldset>`}<div class="actions"><button id="examPrevious" ${a.index===0?'disabled':''}>← Previous</button><button id="examNext" class="primary" ${a.index===items.length-1?'disabled':''}>Next →</button><span class="projection-note">No hints or feedback until the attempt ends.</span></div></article>`;
 $('finishExam').onclick=()=>finish('submitted');$('examFlag').onchange=()=>{if(D.remaining(a)===0){finish('expired');return;}a.flags=$('examFlag').checked?[...new Set([...a.flags,q.id])]:a.flags.filter(id=>id!==q.id);persist();renderQuestionMap();};$('examPrevious').onclick=()=>{a.index--;persist();renderExam();};$('examNext').onclick=()=>{a.index++;persist();renderExam();};
 if(calc){document.querySelectorAll('[data-exam-field]').forEach(input=>input.addEventListener('input',()=>writeAnswer(q.id,input.value,input.dataset.examField)));$('examWork').addEventListener('input',()=>{if(D.remaining(a)===0){finish('expired');return;}a.work[q.id]=$('examWork').value;persist();});drawCalculation(q.geometry);}else document.querySelectorAll('input[name="examAnswer"]').forEach(input=>input.onchange=()=>writeAnswer(q.id,input.value));renderQuestionMap();tick();}
 function drawCalculation(g){let items=[],view='iso';if(g.kind==='resultant'){view='xy';items=[{start:[0,0,0],end:[g.a*Math.cos(g.alpha*Math.PI/180),g.a*Math.sin(g.alpha*Math.PI/180),0],color:'#8cbcff',label:'A',arrow:true},{start:[0,0,0],end:[g.b*Math.cos(g.beta*Math.PI/180),g.b*Math.sin(g.beta*Math.PI/180),0],color:'#efbd77',label:'B',arrow:true}];}else if(g.kind==='cable')items=[{start:[0,0,0],end:g.P,color:'#8cbcff',label:'P',dashed:true},{start:g.P,end:g.Q,color:'#efbd77',label:'Q / cable',arrow:true}];else if(g.kind==='axis')items=[{start:g.A,end:g.B,color:'#b4f178',label:'B / positive axis',arrow:true}];else {view='xy';const unit=g.F.map(v=>v/Math.hypot(...g.F));items=[{start:g.Q,end:g.P,color:'#8cbcff',label:'P',dashed:true},{start:g.P,end:g.P.map((v,i)=>v+unit[i]*2),color:'#b4f178',label:'+F direction',arrow:true},{start:g.Q,end:g.Q.map((v,i)=>v-unit[i]*2),color:'#efbd77',label:'−F direction',arrow:true}];}E.diagram('examCalculationDiagram',view,items);}
 function solutionSymbols(problem){
  Object.assign(Learning.symbols,{examIncludedCos:['cos · included-angle factor','In the parallelogram law, cosine uses the tail-to-tail included angle φ between the two force vectors. It is not necessarily either force’s angle from +x. The formula uses +2AB cos φ.'],examCableDisplacement:['rPQ · cable displacement','For this calculation, rPQ = Q − P points from the force application point P toward the cable’s other endpoint Q, in metres. Normalize this vector to get the cable force direction. It differs from rOP, which starts at the moment reference point O.'],examCableUnit:['uPQ · cable unit direction','The dimensionless unit vector rPQ/|rPQ| points from P toward Q. Multiply by the given cable-force magnitude to obtain Cartesian force components.'],examCableLength:['|rPQ| · cable point distance','The length of Q − P, in metres. Divide all three cable displacement components by this same nonzero length to form uPQ.']});
  const v=(letter,suffix,key)=>taggedVector(letter,suffix,key),norm=markup=>mo('|')+markup+mo('|'),squared=markup=>'<msup>'+markup+'<mn>2</mn></msup>';
  if(problem.id==='calc-resultant')return math(mi('R')+mo('=')+'<msqrt><mrow>'+squared(mi('A'))+mo('+')+squared(mi('B'))+mo('+')+mn(2)+mi('A')+mi('B')+mi('cos','examIncludedCos')+mi('φ','phi')+'</mrow></msqrt>')+math(mi('θ','thetaResult')+mo('=')+mi('atan2')+mo('(')+sub('R','y')+mo(',')+sub('R','x')+mo(')'));
  if(problem.id==='calc-cable'){const rpq=v('r','PQ','examCableDisplacement'),upq=v('u','PQ','examCableUnit');return math(upq+mo('=')+fraction(rpq,symbolMarkup('|rPQ|','examCableLength','<mrow>'+norm(rpq)+'</mrow>')))+math(vector('F','Fvector')+mo('=')+mi('F')+upq)+math(v('M','O','momentVector')+mo('=')+v('r','OP','momentPosition')+mo('×')+vector('F','forceMoment'));}
  if(problem.id==='calc-axis')return math(symbolMarkup('Maxis','axisMomentScalar','<msub><mi>M</mi><mtext>axis</mtext></msub>')+mo('=')+v('u','AB','axisMomentUnit')+mo('·')+v('M','A','axisPointMoment'));
  return math(v('M','c','coupleVector')+mo('=')+v('r','QP','coupleSeparation')+mo('×')+vector('F','coupleForce'))+math(mi('d','coupleArm')+mo('=')+fraction(norm(v('M','c','coupleVector')),norm(vector('F','coupleForce'))));
 }
 function finish(reason){const a=saved.exam;if(a?.status!=='active')return;const now=Date.now();a.status=D.remaining(a,now)===0?'expired':reason;a.finishedAt=a.status==='expired'?a.deadline:now;const grade=D.grade(a);saved.history.push({finishedAt:a.finishedAt,score:grade.score,seed:a.seed});saved.history=saved.history.slice(-10);if(timer!==null){clearInterval(timer);timer=null;}persist();lock(false);mode='exam';$('studyArea').hidden=true;$('examArea').hidden=false;renderResults();}
 function renderResults(){lock(false);const a=saved.exam,result=D.grade(a),topics=Object.fromEntries(Object.keys(D.topics).map(topic=>[topic,{earned:0,total:0}]));for(const item of result.concepts){topics[item.question.topic].earned+=item.earned;topics[item.question.topic].total+=item.points;}for(const item of result.problems){topics[item.problem.topic].earned+=item.earned;topics[item.problem.topic].total+=20;}
 $('examArea').innerHTML=`<article class="panel"><div class="eyebrow">${a.status==='expired'?'TIME EXPIRED · ANSWERS LOCKED':'EXAM SUBMITTED'}</div><h2>Your exam review</h2><div class="score-large">${E.round(result.score)}<small> / 100 points</small></div><p class="projection-note">Numeric answer fields earn partial credit individually. Your written work is retained below for self-review. This score is practice feedback, not your professor’s grading standard.</p><div class="topic-scores">${Object.entries(topics).map(([topic,value])=>`<div><strong>${D.topics[topic]}</strong><span>${E.round(value.earned)} / ${E.round(value.total)}</span></div>`).join('')}</div><div class="actions"><button id="newExam" class="primary">Start another exam</button><button id="backToStudy">Review concepts</button></div></article><article class="panel result-review"><h3>Concept question review</h3>${result.concepts.map((item,i)=>`<details class="review-item"><summary>${i+1}. ${item.correct?'✓ Correct':'○ Review'} · ${D.topics[item.question.topic]} · ${E.round(item.earned)}/${E.round(item.points)}</summary><p class="assessment-prompt">${item.question.prompt}</p><p>Your answer: <strong>${item.answer===undefined?'Unanswered':M.esc(item.question.options[Number(item.answer)]||'Invalid choice')}</strong></p><p>Correct answer: <strong>${item.question.options[item.question.answer]}</strong></p><p>${item.question.explanation}</p><button data-review-lesson="${lessonFor[item.question.topic]}">Open related lesson →</button></details>`).join('')}</article>${result.problems.map(item=>`<article class="panel result-review"><div class="panel-heading"><h3>${item.problem.title}</h3><span class="badge">${item.earned} / 20 POINTS</span></div><p class="assessment-prompt">${item.problem.prompt}</p><table><thead><tr><th>Answer field</th><th>Your answer</th><th>Expected</th><th>Points</th></tr></thead><tbody>${item.fields.map(field=>`<tr><td>${field.label}</td><td>${field.answer===undefined||String(field.answer).trim()===''?'Unanswered':M.esc(field.answer)}</td><td>${E.round(field.value)}</td><td>${field.earned}/${field.points}</td></tr>`).join('')}</tbody></table><h3>Solution guide</h3><ol class="solution-guide">${item.problem.steps.map(step=>`<li>${step}</li>`).join('')}</ol>${a.work[item.problem.id]?`<details class="review-item"><summary>Your saved working</summary><pre class="saved-work">${M.esc(a.work[item.problem.id])}</pre></details>`:''}<button data-review-lesson="${lessonFor[item.problem.topic]}">Open related lesson →</button></article>`).join('')}`;
 document.querySelectorAll('.solution-guide').forEach((list,index)=>list.insertAdjacentHTML('beforebegin',`<div class="math" data-equation="${result.problems[index].problem.title}">${solutionSymbols(result.problems[index].problem)}</div>`));
 $('newExam').onclick=()=>{saved.exam=null;persist();renderExamStart();};$('backToStudy').onclick=()=>setMode('study');bindLessonLinks();}
 document.addEventListener('visibilitychange',()=>{if(saved.exam?.status==='active')tick();});
 persist();if(saved.exam?.status==='active'){showView('assessment');lock(true);setMode('exam');startTimer();}else {lock(false);setMode('study');}
})();
